   219→// handleSessionStartCommon is the shared implementation for session start hooks.
   220→// Used by both Claude Code and Gemini CLI handlers.
   221→func handleSessionStartCommon() error {
   222→	ag, err := GetCurrentHookAgent()
   223→	if err != nil {
   224→		return fmt.Errorf("failed to get agent: %w", err)
   225→	}
   226→
   227→	input, err := ag.ParseHookInput(agent.HookSessionStart, os.Stdin)
   228→	if err != nil {
   229→		return fmt.Errorf("failed to parse hook input: %w", err)
   230→	}
   231→
   232→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   233→	logging.Info(logCtx, "session-start",
   234→		slog.String("hook", "session-start"),
   235→		slog.String("hook_type", "agent"),
   236→		slog.String("model_session_id", input.SessionID),
   237→		slog.String("transcript_path", input.SessionRef),
   238→	)
   239→
   240→	if input.SessionID == "" {
   241→		return errors.New("no session_id in input")
   242→	}
   243→
   244→	// Check for existing legacy session (backward compatibility with date-prefixed format)
   245→	// If found, preserve the old session ID to avoid orphaning state files
   246→	entireSessionID := session.FindLegacyEntireSessionID(input.SessionID)
   247→	if entireSessionID == "" {
   248→		// No legacy session found - use agent session ID directly (new format)
   249→		entireSessionID = input.SessionID
   250→	}
   251→
   252→	if err := paths.WriteCurrentSession(entireSessionID); err != nil {
   253→		return fmt.Errorf("failed to set current session: %w", err)
   254→	}
   255→
   256→	fmt.Printf("Current session set to: %s\n", entireSessionID)
   257→	return nil
   258→}
