   811→// handleClaudeCodePostTask handles the PostToolUse[Task] hook
   812→func handleClaudeCodePostTask() error {
   813→	// Skip on default branch for strategies that don't allow it
   814→	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
   815→		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
   816→		return nil // Don't fail the hook, just skip
   817→	}
   818→
   819→	input, err := parsePostTaskHookInput(os.Stdin)
   820→	if err != nil {
   821→		return fmt.Errorf("failed to parse PostToolUse[Task] input: %w", err)
   822→	}
   823→
   824→	// Extract subagent type from tool_input for logging
   825→	subagentType, taskDescription := ParseSubagentTypeAndDescription(input.ToolInput)
   826→
   827→	// Get agent for logging context
   828→	ag, err := GetCurrentHookAgent()
   829→	if err != nil {
   830→		return fmt.Errorf("failed to get agent: %w", err)
   831→	}
   832→
   833→	// Log parsed input context
   834→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   835→	logging.Info(logCtx, "post-task",
   836→		slog.String("hook", "post-task"),
   837→		slog.String("hook_type", "subagent"),
   838→		slog.String("tool_use_id", input.ToolUseID),
   839→		slog.String("agent_id", input.AgentID),
   840→		slog.String("subagent_type", subagentType),
   841→	)
   842→
   843→	// Determine subagent transcript path
   844→	transcriptDir := filepath.Dir(input.TranscriptPath)
   845→	var subagentTranscriptPath string
   846→	if input.AgentID != "" {
   847→		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, input.AgentID)
   848→		if !fileExists(subagentTranscriptPath) {
   849→			subagentTranscriptPath = ""
   850→		}
   851→	}
   852→
   853→	// Log context to stdout
   854→	logPostTaskHookContext(os.Stdout, input, subagentTranscriptPath)
   855→
   856→	// Parse transcript to extract modified files
   857→	var modifiedFiles []string
   858→	if subagentTranscriptPath != "" {
   859→		// Use subagent transcript if available
   860→		transcript, err := parseTranscript(subagentTranscriptPath)
   861→		if err != nil {
   862→			fmt.Fprintf(os.Stderr, "Warning: failed to parse subagent transcript: %v\n", err)
   863→		} else {
   864→			modifiedFiles = extractModifiedFiles(transcript)
   865→		}
   866→	} else {
   867→		// Fall back to main transcript
   868→		transcript, err := parseTranscript(input.TranscriptPath)
   869→		if err != nil {
   870→			fmt.Fprintf(os.Stderr, "Warning: failed to parse transcript: %v\n", err)
   871→		} else {
   872→			modifiedFiles = extractModifiedFiles(transcript)
   873→		}
   874→	}
   875→
   876→	// Load pre-task state and compute new files
   877→	preState, err := LoadPreTaskState(input.ToolUseID)
   878→	if err != nil {
   879→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-task state: %v\n", err)
   880→	}
   881→	newFiles, err := ComputeNewFilesFromTask(preState)
   882→	if err != nil {
   883→		fmt.Fprintf(os.Stderr, "Warning: failed to compute new files: %v\n", err)
   884→	}
   885→
   886→	// Get repo root for path conversion (not cwd, since Claude may be in a subdirectory)
   887→	// Using cwd would filter out files in sibling directories (paths starting with ..)
   888→	repoRoot, err := paths.RepoRoot()
   889→	if err != nil {
   890→		return fmt.Errorf("failed to get repo root: %w", err)
   891→	}
   892→
   893→	// Filter and normalize paths
   894→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
   895→	relNewFiles := FilterAndNormalizePaths(newFiles, repoRoot)
   896→
   897→	// If no file changes, skip creating a checkpoint
   898→	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 {
   899→		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping task checkpoint\n")
   900→		// Cleanup pre-task state (ignore error - cleanup is best-effort)
   901→		_ = CleanupPreTaskState(input.ToolUseID) //nolint:errcheck // best-effort cleanup
   902→		return nil
   903→	}
   904→
   905→	// Find checkpoint UUID from main transcript (best-effort, ignore errors)
   906→	transcript, _ := parseTranscript(input.TranscriptPath) //nolint:errcheck // best-effort extraction
   907→	checkpointUUID, _ := FindCheckpointUUID(transcript, input.ToolUseID)
   908→
   909→	// Get git author
   910→	author, err := GetGitAuthor()
   911→	if err != nil {
   912→		return fmt.Errorf("failed to get git author: %w", err)
   913→	}
   914→
   915→	// Get the configured strategy
   916→	strat := GetStrategy()
   917→
   918→	// Ensure strategy setup is in place
   919→	if err := strat.EnsureSetup(); err != nil {
   920→		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
   921→	}
   922→
   923→	entireSessionID := currentSessionIDWithFallback(input.SessionID)
   924→
   925→	// Get agent type from the currently executing hook agent (authoritative source)
   926→	var agentType agent.AgentType
   927→	if hookAgent, agentErr := GetCurrentHookAgent(); agentErr == nil {
   928→		agentType = hookAgent.Type()
   929→	}
   930→
   931→	// Build task checkpoint context - strategy handles metadata creation
   932→	// Note: Incremental checkpoints are now created during task execution via handleClaudeCodePostTodo,
   933→	// so we don't need to collect/cleanup staging area here.
   934→	ctx := strategy.TaskCheckpointContext{
   935→		SessionID:              entireSessionID,
   936→		ToolUseID:              input.ToolUseID,
   937→		AgentID:                input.AgentID,
   938→		ModifiedFiles:          relModifiedFiles,
   939→		NewFiles:               relNewFiles,
   940→		DeletedFiles:           nil, // TODO: compute deleted files
   941→		TranscriptPath:         input.TranscriptPath,
   942→		SubagentTranscriptPath: subagentTranscriptPath,
   943→		CheckpointUUID:         checkpointUUID,
   944→		AuthorName:             author.Name,
   945→		AuthorEmail:            author.Email,
   946→		SubagentType:           subagentType,
   947→		TaskDescription:        taskDescription,
   948→		AgentType:              agentType,
   949→	}
   950→
   951→	// Call strategy to save task checkpoint - strategy handles all metadata creation
   952→	if err := strat.SaveTaskCheckpoint(ctx); err != nil {
   953→		return fmt.Errorf("failed to save task checkpoint: %w", err)
   954→	}
   955→
   956→	// Cleanup pre-task state (ignore error - cleanup is best-effort)
   957→	_ = CleanupPreTaskState(input.ToolUseID) //nolint:errcheck // best-effort cleanup
   958→
   959→	return nil
   960→}
