  1000→// markSessionEnded updates the session state with the current time as EndedAt.
  1001→func markSessionEnded(sessionID string) error {
  1002→	state, err := strategy.LoadSessionState(sessionID)
  1003→	if err != nil {
  1004→		return fmt.Errorf("failed to load session state: %w", err)
  1005→	}
  1006→	if state == nil {
  1007→		return nil // No state file, nothing to update
  1008→	}
  1009→
  1010→	now := time.Now()
  1011→	state.EndedAt = &now
  1012→
  1013→	if err := strategy.SaveSessionState(state); err != nil {
  1014→		return fmt.Errorf("failed to save session state: %w", err)
  1015→	}
  1016→	return nil
  1017→}
