  1026→// outputHookResponse outputs a JSON response to stdout for Claude Code hooks.
  1027→// When continueExec is false, Claude will block the current operation and show the reason to the user.
  1028→func outputHookResponse(continueExec bool, reason string) error {
  1029→	resp := hookResponse{
